type MyString string

func (s MyString) IsPalindrome() bool {
	runes := []rune(string(s))
	n := len(runes)
	for i := 0; i < n/2; i++ {
		if runes[i] != runes[n-1-i] {
			return false
		}
	}
	return true
}

